BEGIN;
CREATE FUNCTION pg_temp.check_test(ok boolean,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAIL: %',label; END IF; RAISE NOTICE 'PASS: %',label; END $$;
DO $$
DECLARE bid uuid:=(SELECT id FROM businesses WHERE name='Good Pharmacy'); other_uid uuid:=(SELECT owner_id FROM businesses WHERE name='Pending Pharmacy'); uid uuid:=(SELECT owner_id FROM businesses WHERE name='Good Pharmacy'); mid uuid; oid uuid; doc jsonb; data jsonb; denied boolean; initial_stock numeric; snapshot jsonb; sid uuid; tid uuid; wid uuid:=(SELECT id FROM businesses WHERE name='Alpha Wholesale'); wuid uuid:=(SELECT owner_id FROM businesses WHERE name='Alpha Wholesale');
BEGIN
 SELECT coalesce(sum(stock),0) INTO initial_stock FROM pharmacy_inventory_items WHERE pharmacy_id=bid;
 PERFORM set_config('request.jwt.claim.sub',uid::text,true); SET LOCAL ROLE authenticated;
 data:='{"name":"QA private paracetamol","strength":"500 mg","dosage_form":"tablet","pack_size":"100","unit":"packs","category":"medicine","aliases":"QA alias","generic_name":"acetaminophen"}'::jsonb;
 mid:=public.save_procurement_medicine(bid,data);
 PERFORM pg_temp.check_test(public.save_procurement_medicine(bid,data)=mid,'Exact catalogue creation retry reuses identity');
 PERFORM pg_temp.check_test(jsonb_array_length(public.search_procurement_catalogue(bid,'QA alias','business'))=1,'Alias search finds private medicine');
 PERFORM pg_temp.check_test(jsonb_array_length(public.search_procurement_catalogue(bid,'acetaminophen','business'))=1,'Generic search finds private medicine');
 PERFORM pg_temp.check_test(public.save_procurement_medicine(bid,data||'{"strength":"250 mg"}')<>mid,'Different strengths stay separate');
 oid:=public.save_external_supply_order(bid,'{"kind":"request","supplier":"","lines":[]}',gen_random_uuid());
 denied:=false;BEGIN PERFORM public.transition_external_supply_order(oid,1,'issued');EXCEPTION WHEN OTHERS THEN denied:=true;END;
 PERFORM pg_temp.check_test(denied,'Incomplete draft saves but cannot issue');
 doc:=jsonb_build_object('kind','request','supplier','QA Supplier','lines',jsonb_build_array(jsonb_build_object('id',gen_random_uuid(),'name','QA private paracetamol / 500 mg / tablet / 100','quantity',2,'unit','packs','catalogue_id',mid,'catalogue_source','business','unit_price',NULL)));
 PERFORM public.save_external_supply_order(bid,doc,gen_random_uuid(),oid,1);
 PERFORM public.transition_external_supply_order(oid,2,'issued');
 SELECT o.data INTO snapshot FROM external_supply_orders o WHERE id=oid;
 PERFORM public.save_procurement_medicine(bid,data||'{"aliases":"corrected alias"}',mid,1);
 PERFORM pg_temp.check_test((SELECT o.data=snapshot FROM external_supply_orders o WHERE id=oid),'Catalogue edit does not rewrite issued snapshot');
 denied:=false;BEGIN PERFORM public.save_procurement_medicine(bid,data,mid,1);EXCEPTION WHEN OTHERS THEN denied:=true;END;
 PERFORM pg_temp.check_test(denied,'Stale catalogue version rejected');
 PERFORM pg_temp.check_test((SELECT coalesce(sum(stock),0) FROM pharmacy_inventory_items WHERE pharmacy_id=bid)=initial_stock,'Catalogue and document operations never create stock');

 sid:=public.save_procurement_supplier(bid,'{"name":"QA private supplier","phone":"000","email":"qa@example.test"}');
 PERFORM pg_temp.check_test(public.save_procurement_supplier(bid,'{"name":"QA private supplier","phone":"000","email":"qa@example.test"}')=sid,'Supplier retry is deduplicated');
 PERFORM pg_temp.check_test(jsonb_array_length(public.procurement_suppliers(bid,'qa@example.test'))=1,'Supplier search finds saved email');
 tid:=public.save_procurement_template(bid,'QA list',doc->'lines');
 PERFORM pg_temp.check_test(public.save_procurement_template(bid,'QA list',doc->'lines')=tid,'Template retry reuses identity');
 PERFORM pg_temp.check_test((SELECT lines->0->>'unit_price' IS NULL FROM procurement_templates WHERE id=tid),'Templates never carry agreed prices');
 PERFORM pg_temp.check_test(jsonb_array_length(public.procurement_document_report(bid,NULL,NULL,'QA Supplier'))=1,'Report returns issued line snapshot');
 denied:=false;BEGIN PERFORM public.save_external_supply_order(bid,doc,gen_random_uuid(),oid,3);EXCEPTION WHEN OTHERS THEN denied:=true;END;
 PERFORM pg_temp.check_test(denied,'Issued document cannot be overwritten');
 denied:=false;BEGIN PERFORM public.save_external_supply_order(bid,jsonb_set(doc,'{lines,0,catalogue_source}','null'),gen_random_uuid());EXCEPTION WHEN OTHERS THEN denied:=true;END;
 PERFORM pg_temp.check_test(denied,'Catalogue ID without authorized source rejected');
 denied:=false;BEGIN INSERT INTO business_procurement_catalogue(business_id,data,identity_key,created_by) VALUES(bid,data,'bypass',uid);EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;
 PERFORM pg_temp.check_test(denied,'Direct catalogue writes cannot bypass RPC');
 PERFORM set_config('request.jwt.claim.sub',wuid::text,true);
 PERFORM pg_temp.check_test(public.can_prepare_procurement(wid),'Approved wholesaler may prepare documents');
 PERFORM pg_temp.check_test(public.save_procurement_medicine(wid,data) IS NOT NULL,'Wholesaler has private catalogue');
 PERFORM pg_temp.check_test(public.save_external_supply_order(wid,'{"kind":"request","supplier":"","lines":[]}',gen_random_uuid()) IS NOT NULL,'Wholesaler can save incomplete document');
 PERFORM pg_temp.check_test(NOT public.can_access_external_procurement(wid),'Wholesaler cannot enter pharmacy receiving');
 denied:=false;BEGIN PERFORM public.save_external_supply_order(wid,doc||jsonb_build_object('supplier_id',sid),gen_random_uuid());EXCEPTION WHEN OTHERS THEN denied:=true;END;
 PERFORM pg_temp.check_test(denied,'Cross-business supplier/catalogue references rejected');
 PERFORM set_config('request.jwt.claim.sub',other_uid::text,true);
 PERFORM pg_temp.check_test((SELECT count(*) FROM business_procurement_catalogue WHERE business_id=bid)=0,'RLS hides other business catalogue');
 denied:=false;BEGIN PERFORM public.search_procurement_catalogue(bid,'QA');EXCEPTION WHEN OTHERS THEN denied:=true;END;
 PERFORM pg_temp.check_test(denied,'Unauthorized catalogue RPC rejected');
 denied:=false;BEGIN PERFORM public.save_procurement_medicine(bid,data);EXCEPTION WHEN OTHERS THEN denied:=true;END;
 PERFORM pg_temp.check_test(denied,'Unauthorized catalogue creation rejected');
 denied:=false;BEGIN PERFORM public.procurement_suppliers(bid,'');EXCEPTION WHEN OTHERS THEN denied:=true;END;
 PERFORM pg_temp.check_test(denied,'Unauthorized supplier search rejected');
 RESET ROLE;
END $$;
ROLLBACK;
